use super::{native_compression::{self,CompressionRuntime},native_extraction::ExtractionRuntime,zip_method::ZipMethod,zip_password::ZipEncryption,standard_zip_writer::ZipSplitMode};
use crate::models::compression::{CompressionOptions,DecompressOptions,TaskLogSeverity};
use std::{path::{Path,PathBuf},sync::{Arc,Mutex,atomic::AtomicBool}};
use chrono::TimeZone;
use sha2::{Digest,Sha256};
use anyhow::Result;
fn base()->PathBuf{let p=Path::new(env!("CARGO_MANIFEST_DIR")).join("../test-results/zip-source-time-1724");std::fs::create_dir_all(&p).unwrap();p}
fn sha(path:&Path)->String{format!("{:x}",Sha256::digest(std::fs::read(path).unwrap()))}
fn fields(t:zip_aes::DateTime)->[u16;6]{[t.year(),t.month()as u16,t.day()as u16,t.hour()as u16,t.minute()as u16,t.second()as u16]}
#[derive(Default)]struct Runtime{pool:super::io_buffer_pool::IOBufferPool,threads:Mutex<std::collections::HashSet<std::thread::ThreadId>>}
impl CompressionRuntime for Runtime{
 fn cancellation_flag(&self)->Arc<AtomicBool>{Arc::new(AtomicBool::new(false))}
 fn check_cancellation(&self)->Result<()>{Ok(())}
 fn copy_buffer_size(&self)->usize{65536}
 fn emit_log(&self,_:&tauri::Window,_:&str,_:&str,_:TaskLogSeverity){}
 fn emit_progress(&self,_:&tauri::Window,_:&str,_:f32,_:Option<String>,_:u64,_:u64){}
}
impl ExtractionRuntime for Runtime{
 fn check_cancellation(&self)->Result<()>{self.threads.lock().unwrap().insert(std::thread::current().id());Ok(())}
 fn buffer_pool(&self)->&super::io_buffer_pool::IOBufferPool{&self.pool}
 fn copy_buffer_size(&self)->usize{65536}
 fn normalized_archive_path(&self,path:&Path,preserve:bool)->Option<PathBuf>{if preserve{Some(path.into())}else{path.file_name().map(PathBuf::from)}}
 fn emit_log(&self,_:&tauri::Window,_:&str,_:&str,_:TaskLogSeverity){}
 fn emit_progress(&self,_:&tauri::Window,_:&str,_:f32,_:Option<String>,_:u64,_:u64){}
}
fn stamp(path:&Path,year:i32,month:u32,day:u32,second:u32){let local=chrono::Local.with_ymd_and_hms(year,month,day,12,34,second).single().unwrap();filetime::set_file_mtime(path,filetime::FileTime::from_unix_time(local.timestamp(),123_456_700)).unwrap();}
fn sources()->Vec<String>{let source_tag=format!("{:x}",Sha256::digest(std::thread::current().name().unwrap_or("test").as_bytes()));let root=base().join("source").join(&source_tag[..8]);std::fs::create_dir_all(root.join("tree/empty-dir")).unwrap();let mut seed=1724u32;let data=(0..340_000).map(|_|{seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;seed as u8}).collect::<Vec<_>>();for name in ["a.bin","b.bin"]{std::fs::write(root.join(name),&data).unwrap();stamp(&root.join(name),1996,2,29,57);}std::fs::write(root.join("tree/note.txt"),b"Source time remains meaningful after compression.\n").unwrap();stamp(&root.join("tree/note.txt"),2020,11,1,59);std::fs::write(root.join("tree/empty.dat"),[]).unwrap();stamp(&root.join("tree/empty.dat"),2040,6,1,3);stamp(&root.join("tree/empty-dir"),2018,12,31,1);["a.bin","b.bin","tree"].iter().map(|n|root.join(n).to_string_lossy().into_owned()).collect()}
fn source_records(files:&[String],preserve:bool)->Vec<serde_json::Value>{super::compression_entries::collect(files,preserve,true).unwrap().into_iter().map(|e|{let metadata=e.path.metadata().unwrap();let t=filetime::FileTime::from_last_modification_time(&metadata);serde_json::json!({"path":e.path,"name":e.archive_name,"directory":e.is_dir,"seconds":t.unix_seconds(),"nanos":t.nanoseconds(),"sha256":if e.is_dir{None}else{Some(sha(&e.path))}})}).collect()}
fn inspect(input:&Path)->Vec<serde_json::Value>{let mut zip=zip_aes::ZipArchive::new(super::numeric_volume_reader::ZipInputReader::open(input).unwrap()).unwrap();(0..zip.len()).map(|i|{let e=zip.by_index_raw(i).unwrap();serde_json::json!({"name":e.name(),"date":fields(e.last_modified().unwrap()),"method":format!("{:?}",e.compression()),"bytes":e.size()})}).collect()}
fn verify(input:&Path,password:Option<&str>){assert!(super::compression_verification::verify_native_with_zip_encoding(super::compression_format::CompressionRoute::Zip,input,password,None,||false).unwrap());}

#[test]fn ziptime1724_local_calendar_two_second_precision_and_year_boundaries_are_explicit(){
 for(year,month,day,second,expected,clamped)in[(2000,2,29,59,[2000,2,29,12,34,58],false),(1980,1,1,1,[1980,1,1,12,34,0],false),(2107,12,31,59,[2107,12,31,12,34,58],false),(1970,6,1,0,[1980,1,1,0,0,0],true),(2110,6,1,0,[2107,12,31,23,59,58],true)]{
  let time=chrono::Local.with_ymd_and_hms(year,month,day,12,34,second).single().unwrap();let value=super::zip_creation_time::from_system_time(time.into());assert_eq!(fields(value.date),expected);assert_eq!(value.clamped,clamped);
 }
}

#[test]fn ziptime1724_all_native_methods_password_and_volume_paths_write_source_dates_and_keep_contents(){
 let runtime=Runtime::default();let files=sources();let original=source_records(&files,true);let mut cases=Vec::new();let run=base().join(format!("matrix-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&run).unwrap();
 let mut modes=vec![("store","zip",ZipMethod::Store,None,None),("deflate","zip",ZipMethod::Deflate,None,None),("zstd","zip",ZipMethod::Zstd,None,None),("bzip2","zip",ZipMethod::Bzip2,None,None),("lzma","zip",ZipMethod::Lzma,None,None),("ppmd","zip",ZipMethod::Ppmd,None,None),("xz","zipx",ZipMethod::Deflate,None,None)];
 modes.extend([("aes-standard","zip",ZipMethod::Store,Some(ZipEncryption::Aes256),Some(ZipSplitMode::Standard)),("zipcrypto-numeric","zip",ZipMethod::Deflate,Some(ZipEncryption::Zipcrypto),Some(ZipSplitMode::Numeric)),("zipx-aes-standard","zipx",ZipMethod::Deflate,Some(ZipEncryption::Aes256),Some(ZipSplitMode::Standard))]);
 for(name,format,method,encryption,split)in modes{let output=run.join(format!("{name}.{format}"));let options=CompressionOptions{format:Some(format.into()),level:1,zip_method:method,password:encryption.map(|_|"SourceTime1724!".into()),zip_encryption:encryption.unwrap_or_default(),split_size:split.map(|_|65536),zip_split_mode:split.unwrap_or_default(),preserve_paths:Some(true),..Default::default()};native_compression::zip::compress(&runtime,None,"ziptime1724",&files,&output.to_string_lossy(),options).unwrap();let input=if split==Some(ZipSplitMode::Numeric){output.with_file_name(format!("{name}.{format}.001"))}else{output.clone()};verify(&input,encryption.map(|_|"SourceTime1724!"));let entries=inspect(&input);assert_eq!(entries.len(),original.len());for e in &entries{assert_ne!(e["date"],serde_json::json!([1980,1,1,0,0,0]));}let parts=if split.is_some(){super::archive_volumes::complete_volume_paths(&output).unwrap()}else{vec![output]};cases.push(serde_json::json!({"name":name,"input":input,"parts":parts,"encrypted":encryption.is_some(),"numeric":split==Some(ZipSplitMode::Numeric),"sources":original,"entries":entries}));}
 assert_eq!(source_records(&files,true),original);std::fs::write(base().join("native.json"),serde_json::to_vec_pretty(&cases).unwrap()).unwrap();
}

#[test]fn ziptime1724_flattened_duplicates_empty_roots_and_out_of_range_dates_keep_explicit_policy(){
 let root=base().join("boundaries");std::fs::create_dir_all(root.join("first/empty-root")).unwrap();std::fs::create_dir_all(root.join("second")).unwrap();for(name,year)in[("first/same.txt",1970),("second/same.txt",2110)]{std::fs::write(root.join(name),name).unwrap();stamp(&root.join(name),year,6,1,1);}stamp(&root.join("first/empty-root"),2004,2,29,37);let files=["first/same.txt","second/same.txt","first/empty-root"].iter().map(|p|root.join(p).to_string_lossy().into_owned()).collect::<Vec<_>>();let original=source_records(&files,false);let output=root.join("flattened.zip");native_compression::zip::compress(&Runtime::default(),None,"bounds",&files,&output.to_string_lossy(),CompressionOptions{format:Some("zip".into()),preserve_paths:Some(false),..Default::default()}).unwrap();let entries=inspect(&output);assert_eq!(entries[0]["date"],serde_json::json!([1980,1,1,0,0,0]));assert_eq!(entries[1]["date"],serde_json::json!([2107,12,31,23,59,58]));assert_eq!(entries[1]["name"],"same (1).txt");assert_eq!(source_records(&files,false),original);verify(&output,None);std::fs::write(base().join("boundaries.json"),serde_json::to_vec_pretty(&serde_json::json!({"input":output,"parts":[output],"sources":original,"entries":entries})).unwrap()).unwrap();
}

#[test]fn ziptime1724_created_zip_round_trips_in_both_sequential_and_actual_parallel_extraction(){
 let runtime=Runtime::default();let all=sources();let files=all[..2].to_vec();let original=source_records(&files,true);let output=base().join("parallel-source.zip");native_compression::zip::compress(&runtime,None,"parallel",&files,&output.to_string_lossy(),CompressionOptions{format:Some("zip".into()),..Default::default()}).unwrap();let mut outputs=Vec::new();for parallel in [false,true]{let target=base().join(format!("{}-{}",if parallel{"parallel-restored"}else{"sequential-restored"},uuid::Uuid::new_v4()));std::fs::create_dir_all(&target).unwrap();super::native_extraction::zip::extract_with_optional_window(&runtime,None,"date-roundtrip",output.to_str().unwrap(),target.to_str().unwrap(),None,&DecompressOptions{parallel_zip:parallel,preserve_paths:true,preserve_timestamps:true,..Default::default()}).unwrap();for s in &original{let file=target.join(s["name"].as_str().unwrap());assert_eq!(sha(&file),s["sha256"]);let delta=file.metadata().unwrap().modified().unwrap().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs()as i64-s["seconds"].as_i64().unwrap();assert_eq!(delta,-1);}if parallel{assert!(runtime.threads.lock().unwrap().len()>1,"parallel path must actually use worker threads");}outputs.push(serde_json::json!({"parallel":parallel,"output":target,"workerThreadsObserved":runtime.threads.lock().unwrap().len()}));}std::fs::write(base().join("roundtrip.json"),serde_json::to_vec_pretty(&serde_json::json!({"input":output,"sources":original,"outputs":outputs})).unwrap()).unwrap();
}

#[test]fn ziptime1724_conversion_retains_tar_alias_dates_through_verified_final_zip_and_zipx(){
 let source=Path::new(env!("CARGO_MANIFEST_DIR")).join("../tests/fixtures/archives/tar-browse-links-1719/gnu.tar.lzo");let before=sha(&source);let runtime=Runtime::default();let mut cases=Vec::new();for format in ["zip","zipx"]{let output=base().join(format!("converted.{format}"));let prepared=super::tar_link_conversion::Prepared::open(&source,&output,DecompressOptions{preserve_paths:true,preserve_timestamps:true,..Default::default()},Arc::new(AtomicBool::new(false))).unwrap().unwrap();let files=prepared.read(&runtime,None,"date-conversion").unwrap();let staged=source_records(&files,true);let options=CompressionOptions{format:Some(format.into()),level:1,password:Some("SourceTime1724!".into()),zip_encryption:ZipEncryption::Aes256,preserve_paths:Some(true),..Default::default()};native_compression::zip::compress(&runtime,None,"date-conversion",&files,prepared.rebuilt().to_str().unwrap(),options).unwrap();verify(prepared.rebuilt(),Some("SourceTime1724!"));prepared.publish_verified(false).unwrap();let entries=inspect(&output);assert!(entries.iter().all(|e|e["date"][0]==2023));drop(prepared);assert_eq!(sha(&source),before);cases.push(serde_json::json!({"input":output,"parts":[output],"encrypted":true,"sources":staged,"entries":entries,"sourceTar":source.with_file_name("gnu.tar"),"sourceSha256":before}));}std::fs::write(base().join("conversion.json"),serde_json::to_vec_pretty(&cases).unwrap()).unwrap();
}
